{
  "title": "The Rescue of the Fallen City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined city.",
      "visual_description": "A crumbling wall with a rusted iron gate looms under a grey sky. Old royal banners hang torn from battlements.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn them of danger.",
      "visual_description": "Huddled figures in rags gesture fearfully toward the castle. One points at a distant tower.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Elder Hana", "Young Lira"]
    },
    {
      "scene_number": 3,
      "caption": "They enter through the castle gates.",
      "visual_description": "The portcullis is half-lifted, spikes visible. Moss and ivy cover the stone archway.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower looms ahead, rumors of a dragon within.",
      "visual_description": "A spiraling tower with blackened stones, faint smoke rising from a top window. Bones litter the courtyard.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols block the main courtyard.",
      "visual_description": "Soldiers in dented plate armor march in formation, their shields bearing the old royal crest.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Captain Voss", "Guard 1", "Guard 2"]
    },
    {
      "scene_number": 6,
      "caption": "Mira uses magic to create a distraction.",
      "visual_description": "A shimmering illusion of a fleeing figure darts past a side alley, drawing the patrol's attention.",
      "characters": ["Mira the Mage", "Kael the Ranger", "Torin the Warrior"]
    },
    {
      "scene_number": 7,
      "caption": "They slip through a hidden passage behind a tapestry.",
      "visual_description": "Dusty corridor lit by a single torch, cobwebs hanging low. The tapestry shows a hunting scene.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door with runes blocks their path.",
      "visual_description": "Stone door covered in glowing blue runes, a keyhole shaped like a dragon's eye.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior"]
    },
    {
      "scene_number": 9,
      "caption": "Mira deciphers the runes to open the door.",
      "visual_description": "She traces the runes with her finger, speaking an incantation. The runes pulse and the door grinds open.",
      "characters": ["Mira the Mage", "Kael the Ranger", "Torin the Warrior"]
    },
    {
      "scene_number": 10,
      "caption": "They find the prisoner in a dungeon cell.",
      "visual_description": "Dark cell with straw on the floor, chains on the wall. The prisoner is a young woman in a torn dress.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    },
    {
      "scene_number": 11,
      "caption": "The patrol discovers them and a fight breaks out.",
      "visual_description": "Torches flare as guards rush in, swords drawn. Torin steps forward to meet them.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara", "Captain Voss", "Guard 1", "Guard 2", "Guard 3"]
    },
    {
      "scene_number": 12,
      "caption": "Kael covers their retreat with arrows.",
      "visual_description": "He kneels behind an overturned table, firing arrows that strike shields and helmets, forcing guards back.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    },
    {
      "scene_number": 13,
      "caption": "They flee through a collapsing hallway.",
      "visual_description": "Cracks spider across the ceiling, stones fall. They run under crumbling arches, dust choking the air.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    },
    {
      "scene_number": 14,
      "caption": "The dragon appears on a rooftop.",
      "visual_description": "A massive red dragon perches on a ruined tower, its eyes glowing, smoke curling from its nostrils.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara", "Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "Mira casts a blinding spell to distract the dragon.",
      "visual_description": "A brilliant white light erupts from her hands, causing the dragon to rear back with a roar.",
      "characters": ["Mira the Mage", "Kael the Ranger", "Torin the Warrior", "Princess Elara", "Dragon"]
    },
    {
      "scene_number": 16,
      "caption": "They race toward the escape bridge.",
      "visual_description": "A long stone bridge arches over a chasm, the far end in shadow. Broken statues line the rails.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to collapse behind them.",
      "visual_description": "Stones fall into the chasm as cracks widen. They run, clutching each other, the bridge groaning.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    },
    {
      "scene_number": 18,
      "caption": "They reach safety as the city crumbles in the distance.",
      "visual_description": "On a grassy hill, they watch the ruined city collapse, dust rising. The princess thanks them.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torin the Warrior", "Princess Elara"]
    }
  ]
}

